#include <USB.h>
#include <USBHIDKeyboard.h>

USBHIDKeyboard Keyboard;

// ======== матрица 4x4 ========
const int ROW_PINS[4] = {13, 12, 11, 10};
const int COL_PINS[4] = {9, 8, 7, 6};

const char KEYS[4][4] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};

// ======== утилиты ========
void typeText(const char* s) { Keyboard.print(s); }

void enter() {
  Keyboard.press(KEY_RETURN); delay(30);
  Keyboard.release(KEY_RETURN);
}

// переключаем на английскую раскладку (Alt+Shift)
void toEnglishLayout() {
  Keyboard.press(KEY_LEFT_ALT);
  Keyboard.press(KEY_LEFT_SHIFT);
  delay(20);
  Keyboard.releaseAll();
  delay(60);
}

// Win+R -> команда -> Enter
void runCommand(const char* cmd) {
  toEnglishLayout();
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
  delay(40); Keyboard.releaseAll();
  delay(500);
  typeText(cmd); delay(100); enter();
}

void openCmd() {
  runCommand("cmd");
  delay(800);
}

// Win+X -> A (админ-консоль) -> UAC подтверждаем Enter -> внутри cmd
void adminShell() {
  toEnglishLayout();
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('x');
  delay(40); Keyboard.releaseAll();
  delay(800);                              // ждём меню Win+X
  Keyboard.press('a'); delay(40); Keyboard.releaseAll();
  delay(2500);                             // ждём окно UAC
  Keyboard.press(KEY_RETURN); delay(40);   // "Да"
  Keyboard.release(KEY_RETURN);
  delay(2000);                             // ждём окно консоли
  typeText("cmd"); enter();                // если открылся PowerShell — переходим в cmd
  delay(800);
}

void runInShell(const char* cmd) {
  typeText(cmd); delay(100); enter(); delay(400);
}

// ======== действия кнопок ========

// 1 — диспетчер задач от админа
void btn1() { adminShell(); runInShell("taskmgr"); }

// 2 — regedit от админа
void btn2() { adminShell(); runInShell("regedit"); }

// 3 — планировщик от админа
void btn3() { adminShell(); runInShell("taskschd.msc"); }

// 4 — перезагрузка в BIOS
void btn4() { adminShell(); runInShell("shutdown /r /fw /t 0"); }

// 5 — выключение ПК (5 сек, можно отменить: shutdown -a)
void btn5() { runCommand("shutdown -s -t 5"); }

// 6 — перезагрузка ПК
void btn6() { runCommand("shutdown -r -t 5"); }

// 7 — фейк-ошибка "Удаление Системных файлов" + ребут через 15 сек
void btn7() {
  openCmd();
  // кириллицу собираем из ChrW-кодов, чтобы печатать только ASCII
  typeText(">fake.vbs echo x=MsgBox(ChrW(^&H423)^&ChrW(^&H434)^&ChrW(^&H430)^&ChrW(^&H43B)^&ChrW(^&H435)^&ChrW(^&H43D)^&ChrW(^&H438)^&ChrW(^&H435)^&ChrW(32)^&ChrW(^&H421)^&ChrW(^&H438)^&ChrW(^&H441)^&ChrW(^&H442)^&ChrW(^&H435)^&ChrW(^&H43C)^&ChrW(^&H43D)^&ChrW(^&H44B)^&ChrW(^&H445)^&ChrW(32)^&ChrW(^&H444)^&ChrW(^&H430)^&ChrW(^&H439)^&ChrW(^&H43B)^&ChrW(^&H43E)^&ChrW(^&H432),16,\"ERROR\")");
  enter(); delay(200);
  typeText("start wscript fake.vbs"); enter(); delay(400);
  typeText("shutdown -r -t 15"); enter();
}

// 8 — фейк-предупреждение "Установка TMR-AI..."
void btn8() {
  openCmd();
  typeText(">warn.vbs echo x=MsgBox(ChrW(^&H423)^&ChrW(^&H441)^&ChrW(^&H442)^&ChrW(^&H430)^&ChrW(^&H43D)^&ChrW(^&H43E)^&ChrW(^&H432)^&ChrW(^&H43A)^&ChrW(^&H430)^&\" TMR-AI...\",48,\"WARNING\")");
  enter(); delay(200);
  typeText("start wscript warn.vbs"); enter();
}

// 9 — открыть C:\
void btn9() { runCommand("explorer C:\\"); }

// 10 — открыть C:\Users\<юзер>, а если есть OneDrive — его
void btn10() {
  openCmd();
  typeText("if exist \"%USERPROFILE%\\OneDrive\" (explorer \"%USERPROFILE%\\OneDrive\") else (explorer \"%USERPROFILE%\")");
  enter();
}

// ======== опрос матрицы ========
char scanKeys() {
  for (int c = 0; c < 4; c++) {
    pinMode(COL_PINS[c], OUTPUT);
    digitalWrite(COL_PINS[c], LOW);
    for (int r = 0; r < 4; r++) {
      pinMode(ROW_PINS[r], INPUT_PULLUP);
      if (digitalRead(ROW_PINS[r]) == LOW) {
        pinMode(ROW_PINS[r], INPUT);
        pinMode(COL_PINS[c], INPUT);
        return KEYS[r][c];
      }
      pinMode(ROW_PINS[r], INPUT);
    }
    pinMode(COL_PINS[c], INPUT);
  }
  return 0;
}

void setup() {
  Serial.begin(115200);
  USB.begin();
  Keyboard.begin();
  delay(2000);
  Serial.println("Keypad ready");
}

void loop() {
  char k = scanKeys();
  if (k) {
    switch (k) {
      case '1': btn1();  break;
      case '2': btn2();  break;
      case '3': btn3();  break;
      case '4': btn4();  break;
      case '5': btn5();  break;
      case '6': btn6();  break;
      case '7': btn7();  break;
      case '8': btn8();  break;
      case '9': btn9();  break;
      case '0': btn10(); break;
    }
    delay(3000);
  }
  delay(10);
}
